package com.spidy.servlet;import com.spidy.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws IOException,ServletException{if(!Auth.student(r)){p.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT username,total_xp,player_level,(SELECT COUNT(*) FROM mission_submissions m WHERE m.user_id=users.id AND is_correct=1) completed FROM users WHERE id=?")){s.setInt(1,(Integer)r.getSession().getAttribute("userId"));r.setAttribute("stats",s.executeQuery());r.getRequestDispatcher("dashboard.jsp").forward(r,p);}catch(Exception e){r.getSession().setAttribute("msg",e.getMessage());p.sendRedirect("login.jsp");}}}
